begin;

update public.portfolio_profile
set
  summary_es='MSc. en Gestión Integral de Recursos Hídricos e Ingeniero Agrónomo con experiencia en análisis de datos, SIG, suelos, riego, evaluación ambiental e investigación aplicada. Integro análisis cuantitativo, cartografía, Python, SQL, QGIS, ArcGIS y herramientas de IA para transformar información técnica y geoespacial en decisiones claras.',
  summary_en='MSc. in Integrated Water Resources Management and Agricultural Engineer with experience in data analytics, GIS, soils, irrigation, environmental assessment and applied research. I combine quantitative analysis, mapping, Python, SQL, QGIS, ArcGIS and AI tools to turn technical and geospatial information into clear decisions.',
  github_url='https://github.com/willtvbox5000-wq',
  photo_url='/assets/img/willer-profile-formal.jpg'
where id='main';

insert into public.portfolio_projects(
  slug,title_es,title_en,subtitle_es,subtitle_en,description_es,description_en,
  category,tags,image_url,featured,published,sort_order
) values (
  'masters-thesis-cliza-infiltration','Maestría · Análisis de infiltrabilidad, suelos y riego','Master''s Thesis · Soil Infiltration, GIS and Irrigation Analytics',
  'Cliza, Cochabamba · UMSS / Centro AGUA · 2019','Cliza, Cochabamba · UMSS / Centro AGUA · 2019',
  'Investigación aplicada que integró muestreo de suelos, ensayos de infiltración de doble anillo, regresión y ajuste del modelo de Kostiakov, validación mediante r², análisis espacial y cartografía para traducir la infiltrabilidad en criterios de diseño y manejo de riego por aspersión.','Applied research integrating soil sampling, double-ring infiltration testing, regression and Kostiakov-model fitting, r² validation, spatial analysis and mapping to translate infiltration behavior into sprinkler-irrigation design and management criteria.',
  'data',array['Data Analysis','GIS','Soils','Irrigation','Regression','Research'],'/assets/thesis/infiltrability_map.jpeg',true,true,1
)
on conflict(slug) do update set
  title_es=excluded.title_es,title_en=excluded.title_en,
  subtitle_es=excluded.subtitle_es,subtitle_en=excluded.subtitle_en,
  description_es=excluded.description_es,description_en=excluded.description_en,
  category=excluded.category,tags=excluded.tags,image_url=excluded.image_url,
  featured=excluded.featured,published=excluded.published,sort_order=excluded.sort_order;

update public.portfolio_projects set sort_order=1 where slug='masters-thesis-cliza-infiltration';
update public.portfolio_projects set sort_order=2 where slug='agricultural-data-iniaf';
update public.portfolio_projects set sort_order=3 where slug='deforestation-risk';
update public.portfolio_projects set sort_order=4 where slug='road-network-gis';
update public.portfolio_projects set sort_order=5 where slug='smart-trading-review';
update public.portfolio_projects set sort_order=6 where slug='technified-irrigation';

insert into public.portfolio_case_studies(
  slug,title_es,title_en,type,description_es,description_en,data_json,published,sort_order
) values (
  'masters-thesis-cliza','Tesis de Maestría · Cliza','Master''s Thesis · Cliza',
  'thesis','Evaluación de la infiltrabilidad del suelo como criterio de diseño y manejo de sistemas de riego por aspersión en el municipio de Cliza.','Assessment of soil infiltrability as a criterion for sprinkler-irrigation design and management in the municipality of Cliza.',
  '{"year":2019,"program_es":"Maestría Científica en Gestión Integral de Recursos Hídricos","program_en":"Scientific Master''s in Integrated Water Resources Management","institution":"Universidad Mayor de San Simón · Centro AGUA","study_area_km2":68.15,"slopes_pct":"2–5","soil_density_g_cm3":"1.23–1.59","validated_soil_units":7,"sampled_plots":22,"tests_per_observation":2,"test_duration_hours":"5–7","analysis_methods_es":["Muestreo y caracterización física del suelo: textura, estructura, densidad aparente y porosidad.","Ensayos de infiltración mediante infiltrómetros de doble anillo, con dos pruebas simultáneas por punto de observación.","Curvas de infiltración acumulada y velocidad de infiltración mediante gráficos de dispersión y línea de tendencia potencial.","Ajuste analítico con el modelo de Kostiakov y validación de homogeneidad mediante coeficiente de determinación r².","Clasificación de infiltrabilidad con rangos USDA y análisis espacial por unidades de suelo.","Evaluación de selección, disposición y tiempo de aplicación de aspersores; simulación de disposición con WinSiPP2 12.6."],"analysis_methods_en":["Soil sampling and physical characterization: texture, structure, bulk density and porosity.","Double-ring infiltrometer tests, using two simultaneous tests per observation point.","Accumulated-infiltration and infiltration-rate curves using scatterplots and a power trendline.","Analytical fitting with the Kostiakov model and homogeneity validation using the coefficient of determination r².","USDA infiltration-class classification and spatial analysis by soil unit.","Assessment of sprinkler selection, spacing and application time; sprinkler-layout simulation with WinSiPP2 12.6."],"classes":[{"key":"slow","name_es":"Lenta","name_en":"Slow","area_pct":16.3,"units_es":"Asociación Crespo Pampa","units_en":"Crespo Pampa Association","basic_range_mm_h":"2.91–4.46","accumulated_5h_mm":"37–62","representative_mm_h":null,"max_irrigation":"13 h 44 min","max_irrigation_minutes":824},{"key":"mod_slow","name_es":"Moderadamente lenta","name_en":"Moderately slow","area_pct":62.4,"units_es":"Asociaciones Champa, Ucureña y Cuycuni Pampa","units_en":"Champa, Ucureña and Cuycuni Pampa associations","basic_range_mm_h":"8.12–13.61","accumulated_5h_mm":"84.87–134.46","representative_mm_h":11.9,"representative_accumulated_5h_mm":105.78,"max_irrigation":"4 h 55 min","max_irrigation_minutes":295},{"key":"moderate","name_es":"Moderada","name_en":"Moderate","area_pct":21.0,"units_es":"Asociación Román Calle y Consociaciones Chaqui Mayu y Sensano","units_en":"Román Calle Association and Chaqui Mayu and Sensano consociations","basic_range_mm_h":"15.5–24.8","accumulated_5h_mm":"109–174","representative_mm_h":20.0,"representative_accumulated_5h_mm":126.77,"max_irrigation":"2 h 34 min","max_irrigation_minutes":154}],"design_findings_es":["La infiltrabilidad funciona como criterio de diseño y manejo del riego presurizado a escala parcelaria.","En suelos de infiltrabilidad lenta y moderadamente lenta existe mayor restricción para elegir aspersores con tasas de aplicación altas.","Para un mismo aspersor, en suelos lentos o moderadamente lentos se deben ampliar las distancias entre laterales y aspersores para reducir la tasa de aplicación.","En suelos de infiltrabilidad moderada puede reducirse la separación para aproximar la tasa de aplicación a la infiltrabilidad del suelo.","El tiempo de riego requerido es mayor en suelos de infiltrabilidad lenta y disminuye a medida que aumenta la infiltrabilidad."],"design_findings_en":["Infiltrability is a design and management criterion for pressurized field-scale irrigation.","Slow and moderately slow soils impose greater restrictions on sprinkler selection when application rates are high.","For the same sprinkler, lateral and sprinkler spacing should be increased on slow or moderately slow soils to reduce application rate.","On moderately infiltrating soils, spacing can be reduced to bring application rate closer to soil infiltrability.","Required irrigation time is greatest on slow soils and decreases as infiltrability increases."],"conclusions_es":["Se validaron siete unidades de suelo con alta heterogeneidad espacial: cinco asociaciones y dos consociaciones.","Se identificaron tres clases de infiltrabilidad: lenta, moderadamente lenta y moderada.","La clase moderadamente lenta ocupa la mayor proporción del municipio (62.4%), seguida por la moderada (21%) y la lenta (16.3%); los porcentajes están redondeados en la tesis.","La densidad aparente observada (1.23–1.59 g/cm³) refleja niveles de compactación que afectan la absorción de agua y el crecimiento, pero pueden mejorarse mediante manejo del suelo.","La infiltrabilidad condiciona la elección del aspersor, su disposición y el tiempo de riego.","Para obtener curvas representativas se recomienda realizar al menos dos pruebas de infiltración por parcela y una tercera cuando la variación entre pruebas sea amplia.","En suelos pesados, las pruebas deben extenderse hasta alcanzar la infiltración básica; la tesis recomienda al menos 7 horas cuando sea necesario."],"conclusions_en":["Seven soil units with marked spatial heterogeneity were validated: five associations and two consociations.","Three infiltrability classes were identified: slow, moderately slow and moderate.","The moderately slow class covers the largest share of the municipality (62.4%), followed by moderate (21%) and slow (16.3%); percentages are rounded in the thesis.","Observed bulk density (1.23–1.59 g/cm³) indicates compaction levels that affect water uptake and plant growth but can be improved through soil management.","Infiltrability conditions sprinkler selection, spacing and irrigation duration.","At least two infiltration tests per field are recommended for representative curves, with a third test when variability is high.","On heavy soils, tests should continue until basic infiltration is reached; the thesis recommends at least 7 hours when needed."],"maps":[{"title_es":"Mapa validado de unidades de suelo","title_en":"Validated soil-unit map","url":"/assets/thesis/soil_units_validated_map.jpeg","caption_es":"Siete unidades de suelo validadas a partir de trabajo de campo y cartografía base.","caption_en":"Seven soil units validated using fieldwork and base mapping."},{"title_es":"Mapa de clasificación por infiltrabilidad","title_en":"Infiltrability classification map","url":"/assets/thesis/infiltrability_map.jpeg","caption_es":"Distribución espacial de las clases lenta, moderadamente lenta y moderada.","caption_en":"Spatial distribution of slow, moderately slow and moderate classes."},{"title_es":"Mapa de ubicación del municipio","title_en":"Municipality location map","url":"/assets/thesis/location_map.png","caption_es":"Localización de Cliza en Cochabamba, Bolivia.","caption_en":"Location of Cliza in Cochabamba, Bolivia."}]}'::jsonb,true,0
)
on conflict(slug) do update set
  title_es=excluded.title_es,title_en=excluded.title_en,type=excluded.type,
  description_es=excluded.description_es,description_en=excluded.description_en,
  data_json=excluded.data_json,published=excluded.published,sort_order=excluded.sort_order;

commit;
